// JUnit 5 模块化架构
module com.company.testing {
    requires org.junit.jupiter.api;
    requires org.junit.jupiter.engine;
    requires org.junit.platform.commons;
    requires org.junit.platform.engine;

    exports com.company.testing.unit;
    exports com.company.testing.integration;
    opens com.company.testing.unit to org.junit.platform.commons;
    opens com.company.testing.integration to org.junit.platform.commons;
}

// build.gradle - JUnit 5 Gradle配置
plugins {
    id 'java'
    id 'jacoco'
}

group = 'com.company'
version = '1.0.0'
sourceCompatibility = '17'

repositories {
    mavenCentral()
}

dependencies {
    // JUnit 5 dependencies
    testImplementation 'org.junit.jupiter:junit-jupiter-api:5.10.1'
    testImplementation 'org.junit.jupiter:junit-jupiter-params:5.10.1'
    testRuntimeOnly 'org.junit.jupiter:junit-jupiter-engine:5.10.1'
    testRuntimeOnly 'org.junit.vintage:junit-vintage-engine:5.10.1'

    // Mockito
    testImplementation 'org.mockito:mockito-core:5.7.0'
    testImplementation 'org.mockito:mockito-junit-jupiter:5.7.0'

    // AssertJ
    testImplementation 'org.assertj:assertj-core:3.24.2'

    // Testcontainers
    testImplementation 'org.testcontainers:testcontainers:1.19.3'
    testImplementation 'org.testcontainers:junit-jupiter:1.19.3'
    testImplementation 'org.testcontainers:postgresql:1.19.3'

    // Spring Boot Test (如果使用Spring)
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

test {
    useJUnitPlatform {
        includeEngines 'junit-jupiter'
        excludeEngines 'junit-vintage'
        includeTags 'fast'
        excludeTags 'slow'
    }

    // 并行测试配置
    maxParallelForks = Runtime.runtime.availableProcessors().intdiv(2) ?: 1
    forkEvery = 100

    // 测试报告配置
    testLogging {
        events "passed", "skipped", "failed"
        exceptionFormat "full"
        showCauses true
        showExceptions true
        showStackTraces true
    }

    // 系统属性传递
    systemProperty 'junit.jupiter.extensions.autodetection.enabled', 'true'
    systemProperty 'junit.jupiter.execution.parallel.enabled', 'true'
}

// 集成测试任务
task integrationTest(type: Test) {
    useJUnitPlatform {
        includeTags 'integration'
    }

    shouldRunAfter test
    finalizedBy jacocoTestReport
}

check.dependsOn integrationTest

// JaCoCo代码覆盖率配置
jacoco {
    toolVersion = "0.8.11"
}

jacocoTestReport {
    dependsOn test
    reports {
        xml.required = true
        html.required = true
        csv.required = false
    }

    afterEvaluate {
        classDirectories.setFrom(files(classDirectories.files.collect {
            fileTree(dir: it, exclude: [
                '**/*Config.*',
                '**/*Application.*',
                '**/*Dto.*',
                '**/*Entity.*'
            ])
        }))
    }
}

